$ErrorActionPreference = "Stop"\n$root = Split-Path -Parent $MyInvocation.MyCommand.Path\n$target = Read-Host "Ruta del proyecto EvolvAI existente"\nif (-not (Test-Path (Join-Path $target "pubspec.yaml"))) { throw "No se encontró pubspec.yaml en $target" }\nCopy-Item -Recurse -Force (Join-Path $root "lib") (Join-Path $target "lib")\nCopy-Item -Recurse -Force (Join-Path $root "test") (Join-Path $target "test")\nCopy-Item -Force (Join-Path $root "pubspec.yaml") (Join-Path $target "pubspec.yaml")\nWrite-Host "EvolvAI v0.8.4 actualizada sin tocar la carpeta android."\n